let domain = $.input.domain.trim().toLowerCase();
domain = domain.replace(/^(https?:\/\/)?(www\.)?/, '').replace(/\/$/, '').replace(/^@/, '');
if (!domain || !domain.includes('.')) throw new Error('Invalid domain. Provide a bare domain like "apollo.io"');
return { domain };

const resp = $.steps.enrichOrg.response || {};
const org = resp.organization;

if (!org) return { found: false, summary: 'No organization found for domain: ' + $.steps.validateDomain.output.domain };

const funding = (org.funding_events || []).map(f => ({
  type: f.type,
  date: f.date,
  amount: f.amount,
  currency: f.currency,
  investors: f.investors
}));

const technologies = org.technology_names || [];
const deptHeadcount = org.departmental_head_count || {};

return {
  found: true,
  organization: {
    id: org.id,
    name: org.name,
    domain: org.primary_domain,
    website: org.website_url,
    industry: org.industry,
    industries: org.industries || [],
    description: org.short_description || org.seo_description || '',
    employees: org.estimated_num_employees,
    revenue: org.annual_revenue_printed,
    revenueNumeric: org.annual_revenue,
    totalFunding: org.total_funding_printed,
    latestFundingStage: org.latest_funding_stage,
    latestFundingDate: org.latest_funding_round_date,
    foundedYear: org.founded_year,
    location: {
      address: org.raw_address,
      city: org.city,
      state: org.state,
      country: org.country,
      postalCode: org.postal_code
    },
    social: {
      linkedin: org.linkedin_url,
      twitter: org.twitter_url,
      facebook: org.facebook_url
    },
    keywords: org.keywords || []
  },
  funding,
  technologies,
  departmentHeadcount: deptHeadcount,
  summary: `${org.name} | ${org.industry || 'Unknown industry'} | ${org.estimated_num_employees || '?'} employees | ${org.annual_revenue_printed || '?'} revenue | ${org.latest_funding_stage || 'No funding data'}`
};
